namespace sv_58a5063895ea43818136544ba653de7e.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;
    private readonly Random _random = new();

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must marshal to UI thread
    /// via InvokeAsync before calling StateHasChanged.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>Simulates a database query for low-stock items.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs live alerts becomes active.
    /// Polling starts on the first subscriber and stops when the last one leaves.
    /// </summary>
    public async Task StartPollingAsync()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _pollCts = new CancellationTokenSource();
            // Fetch immediately so the first render has data
            await RefreshAsync();
            _ = PollLoopAsync(_pollCts.Token);
        }
    }

    /// <summary>Call when a component that subscribed leaves the page.</summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (!ct.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await RefreshAsync();
            }
        }
        catch (TaskCanceledException)
        {
            // Expected on disposal / navigation away
        }
    }

    private async Task RefreshAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        await NotifySubscribersAsync();
    }

    private async void HandleWarehouseChanged()
    {
        // Warehouse changed — refresh immediately so all components see new data
        await RefreshAsync();
    }

    private async Task NotifySubscribersAsync()
    {
        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _pollCts?.Cancel();
        _pollCts?.Dispose();
    }
}

