@page "/dashboard"
@rendermode InteractiveServer
@using sv_58a5063895ea43818136544ba653de7e.Services
@using sv_58a5063895ea43818136544ba653de7e.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>📊 Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card text-white @(_lowStockCount > 5 ? "bg-danger" : _lowStockCount > 0 ? "bg-warning" : "bg-success")">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4">@_lowStockCount</p>
                <p class="card-text">
                    items below minimum level at <strong>@WarehouseState.CurrentWarehouseName</strong>
                </p>
                <small class="opacity-75">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Site</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
                <p class="card-text text-muted">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Alert Badge Preview</h5>
                <p class="mt-3">
                    Sidebar badge: <AlertBadge />
                </p>
                <p class="text-muted">
                    This badge shares the same data as the one in the sidebar navigation.
                    When polling detects new data, both update simultaneously.
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Log</h5>
                <div class="log-container border rounded p-2 bg-light" style="max-height: 200px; overflow-y: auto;">
                    @if (_logEntries.Count == 0)
                    {
                        <p class="text-muted mb-0">Waiting for first poll…</p>
                    }
                    else
                    {
                        @foreach (var entry in _logEntries.AsEnumerable().Reverse())
                        {
                            <div><code>@entry</code></div>
                        }
                    }
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    private int _lowStockCount;
    private readonly List<string> _logEntries = new();

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChangedAsync;

        // Start polling — this component owns the polling lifecycle
        await AlertService.StartPollingAsync();
        _lowStockCount = AlertService.LatestLowStockCount;
        _logEntries.Add($"[{DateTime.Now:HH:mm:ss}] Initial load — {_lowStockCount} low-stock items at {WarehouseState.CurrentWarehouseId}");
    }

    private async Task OnAlertDataChangedAsync()
    {
        _lowStockCount = AlertService.LatestLowStockCount;
        _logEntries.Add($"[{DateTime.Now:HH:mm:ss}] Poll — {_lowStockCount} low-stock items at {WarehouseState.CurrentWarehouseId}");
        await InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseChanged()
    {
        _ = InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChangedAsync;
        AlertService.StopPolling();
    }
}

